    $fallback->execute([$slug]);
    $fallbackRow=$fallback->fetch();
    $product=$fallbackRow?normalize_product_row($fallbackRow):null;
    if ($product) {
        try {
            $fallbackProducts = apply_active_festivals_to_products([$product]);
            $product = $fallbackProducts[0] ?? $product;
