$displayWarranty=trim((string)($defaultVariant['warranty']??''))?:trim((string)$product['warranty']);if($displayWarranty==='')$displayWarranty='بدون گارانتی';$authenticityGuarantee=(int)($product['authenticity_guarantee']??0);$safeShippingGuarantee=(int)($product['safe_shipping_guarantee']??0);$festivalFreeShipping=(int)($product['festival_enabled']??0)&&(int)($product['festival_free_shipping']??0);$festivalHasPrice=$displayBase>$displayPrice;
