$baseMetaTitle=$product['meta_title']?:$product['title'];$pageKey='product';$pageTitle=$baseMetaTitle.($variantPageLabel!==''?' - '.$variantPageLabel:'').' | '.setting('store_name');$pageDescription=$product['meta_description']?:text_substr(strip_tags((string)($product['description'] ?? '')),0,155);if($variantPageLabel!==''&&!str_contains($pageDescription,$variantPageLabel))$pageDescription=text_substr($pageDescription.'؛ مدل '.$variantPageLabel,0,165);$pageImage=(string)$displayImage;$breadcrumbs=[['name'=>'خانه','url'=>app_url()],['name'=>'فروشگاه','url'=>app_url('shop.php')],['name'=>$product['category_name'],'url'=>app_url('shop.php?category='.rawurlencode($product['category_slug']))],['name'=>$product['title'],'url'=>$productBaseCanonical]];
