};
$schema=['@context'=>'https://schema.org','@type'=>$variants?'ProductGroup':'Product','@id'=>$productBaseCanonical.'#product','url'=>$productBaseCanonical,'name'=>$product['title'],'image'=>$productImages,'description'=>seo_clean_text((string)$product['description'],5000),'sku'=>$product['sku'],'brand'=>['@type'=>'Brand','name'=>$product['brand_name']],'category'=>$product['category_name']];
