        $variantUrl=$productBaseCanonical.'?variant='.(int)$variant['id'];
        $node=['@type'=>'Product','@id'=>$variantUrl.'#product','url'=>$variantUrl,'name'=>trim($product['title'].' '.$variant['option_label']),'sku'=>$variant['sku'],'image'=>[(string)$variant['image']],'description'=>seo_clean_text((string)$product['description'],5000),'brand'=>['@type'=>'Brand','name'=>$product['brand_name']],'isVariantOf'=>['@id'=>$productBaseCanonical.'#product'],'additionalProperty'=>[],'offers'=>$offerFor($variant,$variantUrl)];
        foreach((array)$variant['options'] as $option){$optionName=(string)($option['attribute_name']??'ویژگی');$optionValue=(string)($option['value']??'');$node['additionalProperty'][]=['@type'=>'PropertyValue','name'=>$optionName,'value'=>$optionValue];$optionSlug=strtolower(trim((string)($option['attribute_slug']??'')));if((string)($option['display_type']??'')==='color'||in_array($optionSlug,['color','colour','rang'],true)||$optionName==='رنگ')$node['color']=$optionValue;elseif(in_array($optionSlug,['size','dimension','dimensions'],true)||$optionName==='اندازه'||$optionName==='سایز')$node['size']=$optionValue;elseif(in_array($optionSlug,['material','jens'],true)||$optionName==='جنس')$node['material']=$optionValue;elseif(in_array($optionSlug,['pattern','tarh'],true)||$optionName==='طرح')$node['pattern']=$optionValue;}
        if($node['additionalProperty']===[])unset($node['additionalProperty']);
        $schema['hasVariant'][]=$node;
    }
